//! Inputs of the sleep score, derived from a night's data: the motion-seconds handling and the
//! epoch scan build the arguments of [`super::sleep_score::sleep_score`]. See
//! `docs/algorithms/metrics.md`; the vectors in the tests are generated by
//! `tools/gen_public_vectors_sleep.py`.
//!
//! The scan lays a night on a table of 30-second epochs, aligned down to a multiple of 30 s
//! from the bedtime start: `n = end / 30 - start / 30` rows, at most [`ROWS`]. Row `i` holds the
//! `i`-th usable sleep stage (1 deep, 2 light, 3 REM, 4 awake, 0 reads as awake) and a trailing
//! four-sample sum of the motion bytes. The scan visits rows `0..=min(n, 0x707)` (the row after
//! the last night epoch is read too) and counts the stages, the latency, the wake-ups, the
//! epochs with motion while asleep and the motion bursts. The heart-rate, breathing and quality
//! features of each row do not enter the score and are not modeled.

use super::readiness_inputs::{get_daily_sleep, DailySleep, SleepPeriod};
use super::sleep_score::{sleep_score, Sleep, Timing};

/// Table capacity: 1800 epochs of 30 s.
pub const ROWS: usize = 0x708;
const SCAN_MAX: usize = 0x707;

/// Night data that reaches the score (the fields of the sleep score input).
#[derive(Clone, Copy, Debug)]
pub struct Night<'a> {
    pub age: u8,
    /// Bedtime start and end, Unix seconds.
    pub bed_start_s: i64,
    pub bed_end_s: i64,
    /// Time zone offset of the bedtime start, minutes.
    pub tz_min: i32,
    /// Packed stage nibbles (low nibble first).
    pub phases: &'a [u8],
    /// Time of the first stage, Unix milliseconds.
    pub phase_start_ms: i64,
    /// Motion bytes, one per 30 s; ignored when shorter than the epoch count.
    pub motion: &'a [u8],
    pub motion_start_ms: i64,
    /// (chronotype type, ideal sleep midpoint in seconds).
    pub chronotype: Option<(u8, i32)>,
}

/// Result of the epoch scan.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Scan {
    pub time_in_bed: u16,
    pub deep: u16,
    pub light: u16,
    pub rem: u16,
    /// Epochs; see `docs/algorithms/metrics.md` for the 0, 1 and 0xff values.
    pub latency: u8,
    pub wake_ups: u8,
    pub restless: u16,
    pub got_up: u8,
    /// Mean of (epoch index + 1) over asleep epochs.
    pub midpoint: u32,
    /// min(n, 0x707); the score runs from 10 on.
    pub visited: usize,
}

/// Total score and contributors for a night.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NightScore {
    pub total: u32,
    /// Total sleep, deep, REM, efficiency, latency, restfulness, timing.
    pub contributors: [u32; 7],
    pub sleep: Sleep,
    pub timing: Timing,
    pub scan: Scan,
}

fn trunc_div(a: i64, b: i64) -> i64 {
    a / b
}

/// Rows of the table for a bedtime period.
pub fn epoch_count(start_s: i64, end_s: i64) -> usize {
    let q = (end_s - end_s.rem_euclid(30) - (start_s - start_s.rem_euclid(30))).div_euclid(30);
    let low = (q & 0xFFFF) as usize;
    if low > ROWS {
        ROWS
    } else {
        low
    }
}

/// Packed stage nibbles to one code per epoch. A byte below 0x10 holds a last epoch; a nibble
/// above 4 reads as 0.
pub fn unpack_phases(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(data.len() * 2);
    for &b in data {
        let low = b & 0xF;
        out.push(if low > 4 { 0 } else { low });
        if b < 0x10 {
            break;
        }
        out.push(if b > 0x4F { 0 } else { b >> 4 });
    }
    out
}

/// Stage per table row: phase `k` has time `phase_start_s + 30 k` rounded to the nearest 30 s;
/// phases earlier than the next row are skipped and the others fill the rows in order.
pub fn place_phases(codes: &[u8], phase_start_s: i64, bed_start_s: i64) -> [u8; ROWS] {
    let mut rows = [0u8; ROWS];
    let t0 = bed_start_s - bed_start_s.rem_euclid(30);
    let mut j = 0usize;
    for (k, &code) in codes.iter().enumerate() {
        if j == ROWS {
            break;
        }
        let r = (phase_start_s + 30 * k as i64 + 15).div_euclid(30) * 30;
        if r >= t0 + 30 * j as i64 {
            rows[j] = code;
            j += 1;
        }
    }
    rows
}

/// Motion field per table row: kept sample `q`
/// contributes the sum of the last four kept samples (fewer at the start), modulo 256, to row
/// `first + q`.
pub fn motion_rows(motion: &[u8], motion_start_s: i64, bed_start_s: i64) -> [u8; ROWS] {
    let mut rows = [0u8; ROWS];
    let t0 = bed_start_s - bed_start_s.rem_euclid(30);
    let count = motion.len();
    let mut grid_start = motion_start_s - motion_start_s.rem_euclid(30);
    let (mut first, mut skip) = (0usize, 0usize);
    if grid_start > t0 {
        first = (((grid_start - t0 + 29) / 30) as usize).min(SCAN_MAX);
    } else {
        while grid_start < t0 && skip + 1 < count {
            grid_start += 30;
            skip += 1;
        }
    }
    let mut keep = count - skip;
    if keep >= 0x709 {
        keep = 0x708;
    }
    if keep == 0 {
        return rows;
    }
    let m = &motion[skip..skip + keep];
    let ncopy = (keep - 1).min(SCAN_MAX - first) + 1;
    for k in 0..ncopy {
        let lo = k.saturating_sub(3);
        rows[first + k] = m[lo..=k].iter().fold(0u8, |a, &b| a.wrapping_add(b));
    }
    rows
}

/// The epoch loop.
pub fn scan(phase: &[u8; ROWS], motion: &[u8; ROWS], n: usize) -> Scan {
    let last = n.min(SCAN_MAX);
    let mut cnt = [0u32; 5];
    let mut run: i32 = 0; // signed byte: asleep run (+) or awake run (-), saturating at 127
    let mut onset = false;
    let mut asleep_flag = false;
    let mut wakes = 0u32;
    let mut k = 0u32; // consecutive asleep epochs, saturating at 255
    let mut latency = 0u8;
    let mut armed = true;
    let mut calm = 0u32;
    let mut got_up = 0u32;
    let mut restless = 0u32;
    let mut idx_sum = 0u32;
    let mut hist = [0i32; 3]; // motion rows i-1, i-2, i-3
    for i in 0..=last {
        let mi = motion[i] as i32;
        let eff = if phase[i] == 0 { 4 } else { phase[i] } as usize;
        if eff > 4 {
            break;
        }
        cnt[eff] += 1;
        let asleep;
        let knext;
        if eff == 4 {
            run = run.min(0) - i32::from(run > -127);
            asleep = false;
            if onset && run <= -2 {
                onset = false;
                wakes += 1;
                asleep_flag = false;
            }
            knext = 0;
        } else {
            run = if run == 127 { 127 } else { run.max(0) + 1 };
            asleep = true;
            if !onset && (i as i32 + 1).min(20) <= run {
                onset = true;
                asleep_flag = true;
            }
            if k == 0xFF {
                knext = 0xFF;
            } else {
                knext = k + 1;
                if k >= 9 && latency == 0 {
                    latency = if i < 10 {
                        1
                    } else if i > 0x108 {
                        0xFF
                    } else {
                        (i + 1 - 10) as u8
                    };
                }
            }
        }
        let m3 = hist[2].max(hist[1]);
        let d = (mi - m3).max(0);
        if armed && m3 >= 24 && d >= 24 {
            got_up += 1;
            armed = false;
            calm = 0;
        } else if d >= 24 {
            calm = 0;
        } else if calm != 0xFF {
            calm += 1;
        }
        if !armed && (i as u32 + 1).min(20) <= calm {
            armed = true;
        }
        if mi != 0 && eff != 4 {
            restless += 1;
        }
        if asleep {
            idx_sum = idx_sum.wrapping_add(i as u32 + 1);
        }
        k = knext;
        hist = [mi, hist[0], hist[1]];
    }
    if wakes & 0xFF != 0 && !asleep_flag {
        wakes -= 1;
    }
    let (deep, light, rem) = (cnt[1], cnt[2], cnt[3]);
    let total = (light + deep + rem) & 0xFFFF;
    let midpoint = if total == 0 {
        0
    } else {
        idx_sum.wrapping_add(total >> 1) / total
    };
    Scan {
        time_in_bed: (last + 1) as u16,
        deep: deep as u16,
        light: light as u16,
        rem: rem as u16,
        latency,
        wake_ups: wakes as u8,
        restless: restless as u16,
        got_up: got_up as u8,
        midpoint,
        visited: last,
    }
}

/// Local time of the bedtime start in minutes, folded to -720..719.
pub fn local_clock_minutes(start_s: i64, tz_min: i32) -> i32 {
    let local = start_s + tz_min as i64 * 60;
    let h = local.div_euclid(3600).rem_euclid(24) as i32;
    let m = local.div_euclid(60).rem_euclid(60) as i32;
    h * 60 + m - if h > 11 { 1440 } else { 0 }
}

/// Arguments of [`super::sleep_score::sleep_score`] for a scan.
pub fn score_args(
    age: u8,
    sc: &Scan,
    clock: i32,
    chronotype: Option<(u8, i32)>,
) -> (Sleep, Timing) {
    let (day, reference) = match chronotype {
        Some((t, ideal_s)) => (t, trunc_div(ideal_s as i64, 60) as i32),
        None => (0xFF, 0),
    };
    let mid = clock + ((sc.midpoint as i32 + 1) >> 1);
    (
        Sleep {
            age,
            time_in_bed: sc.time_in_bed,
            deep: sc.deep,
            light: sc.light,
            rem: sc.rem,
            latency: sc.latency,
            restless: sc.wake_ups,
            tosses: sc.restless,
            ext: sc.got_up,
        },
        Timing {
            mid: mid as i16,
            day,
            reference,
        },
    )
}

/// Total score and seven contributors from a night's data. `None` when fewer than 10 epochs
/// were scanned (no score is written).
pub fn night_to_score(night: &Night) -> Option<NightScore> {
    let n = epoch_count(night.bed_start_s, night.bed_end_s);
    let phases = place_phases(
        &unpack_phases(night.phases),
        trunc_div(night.phase_start_ms, 1000),
        night.bed_start_s,
    );
    // Fewer motion samples than epochs: the motion is skipped.
    let motion = if night.motion.len() >= n {
        motion_rows(
            night.motion,
            trunc_div(night.motion_start_ms, 1000),
            night.bed_start_s,
        )
    } else {
        [0u8; ROWS]
    };
    let sc = scan(&phases, &motion, n);
    if sc.visited < 10 {
        return None;
    }
    let clock = local_clock_minutes(night.bed_start_s, night.tz_min);
    let (sleep, timing) = score_args(night.age, &sc, clock, night.chronotype);
    let (contributors, total) = sleep_score(&sleep, timing);
    Some(NightScore {
        total,
        contributors,
        sleep,
        timing,
        scan: sc,
    })
}

/// [`night_to_score`] for stages given per 30-second epoch rather than as the ring's packed
/// phase data, with motion as timestamped samples.
///
/// Stage `k` (1 deep, 2 light, 3 REM, 4 awake) covers `[floor30(bed_start_s) + 30 k, +30 s)`,
/// the grid the stager works on. [`place_phases`] reads the time of a phase relative to the
/// bedtime start, so with a start off the 30 s grid the stages would shift one row early and
/// the first would fall outside; this places each stage in its row instead. Rows without a
/// stage stay 0. `motion` holds `(unix seconds, motion seconds)` points, each assigned to the
/// row of its time relative to `bed_start_s`.
pub fn night_from_stages(
    age: u8,
    bed_start_s: i64,
    bed_end_s: i64,
    tz_min: i32,
    stages: &[u8],
    motion: &[(f64, f64)],
    chronotype: Option<(u8, i32)>,
) -> Option<NightScore> {
    if stages.is_empty() || bed_end_s <= bed_start_s {
        return None;
    }
    let epochs = epoch_count(bed_start_s, bed_end_s);
    let lead = bed_start_s.rem_euclid(30);
    let mut codes = vec![0u8; epochs];
    for (k, &stage) in stages.iter().enumerate() {
        let row = (30 * k as i64 - lead).div_euclid(30);
        if (0..epochs as i64).contains(&row) {
            codes[row as usize] = stage.min(15);
        }
    }
    let packed: Vec<u8> = codes.chunks(2).map(|c| c[0] | c.get(1).map_or(0, |h| h << 4)).collect();
    let mut bytes = vec![0u8; epochs];
    for &(t, sec) in motion {
        let row = ((t - bed_start_s as f64) / 30.0).floor();
        if row >= 0.0 && (row as usize) < epochs {
            bytes[row as usize] = sec.round().clamp(0.0, 255.0) as u8;
        }
    }
    night_to_score(&Night {
        age,
        bed_start_s,
        bed_end_s,
        tz_min,
        phases: &packed,
        phase_start_ms: bed_start_s * 1000,
        motion: &bytes,
        motion_start_ms: bed_start_s * 1000,
        chronotype,
    })
}

/// The [`SleepPeriod`] built from a night's scan: epochs become seconds, time in bed
/// is one epoch less than the scan's row count, latency and midpoint one epoch more, and
/// efficiency is the rounded percent of time in bed spent asleep.
pub fn period_from_scan(sc: &Scan, bed_start_s: i64, tz_min: i32, is_main: u32) -> SleepPeriod {
    let tib = (sc.time_in_bed as u32).saturating_sub(1);
    let total = sc.deep as u32 + sc.light as u32 + sc.rem as u32;
    SleepPeriod {
        is_main,
        start: bed_start_s,
        tz: tz_min,
        time_in_bed: tib * 30,
        total_sleep: total * 30,
        rem: sc.rem as u32 * 30,
        deep: sc.deep as u32 * 30,
        efficiency: if tib != 0 { (200 * total + tib) / (2 * tib) } else { 0 },
        latency: sc.latency as u32 * 30,
        wake_ups: sc.wake_ups as u32,
        restless: sc.restless as u32,
        got_up: sc.got_up as u32,
        midpoint: sc.midpoint,
        ..Default::default()
    }
}

/// Daily sleep score and contributors: the daily sleep output for the period built by
/// [`period_from_scan`] (main period). `chrono` is (type, ideal midpoint in seconds); `None`
/// is the default (0, 0). Contributors are in the order total sleep, deep, REM,
/// efficiency, latency, restfulness, timing.
pub fn app_sleep_score(
    sc: &Scan,
    age: u32,
    bed_start_s: i64,
    tz_min: i32,
    chrono: Option<(u8, i32)>,
) -> DailySleep {
    let (ctype, cmid) = chrono.unwrap_or((0, 0));
    get_daily_sleep(age, ctype, cmid / 60, &[period_from_scan(sc, bed_start_s, tz_min, 1)])
}

#[cfg(test)]
mod tests {
    use super::*;
    // Random scans scored by the Python port (tools/sleep_score_inputs.py).
    include!("sleep_inputs_app_vectors.rs");

    #[test]
    fn app_score_matches_python_port() {
        assert!(!APP_CASES.is_empty());
        for (i, v) in APP_CASES.iter().enumerate() {
            let sc = Scan {
                time_in_bed: v.scan[0] as u16,
                deep: v.scan[1] as u16,
                light: v.scan[2] as u16,
                rem: v.scan[3] as u16,
                latency: v.scan[4] as u8,
                wake_ups: v.scan[5] as u8,
                restless: v.scan[6] as u16,
                got_up: v.scan[7] as u8,
                midpoint: v.scan[8],
                visited: 0,
            };
            let p = period_from_scan(&sc, v.start, v.tz, 1);
            assert_eq!(p.efficiency, v.efficiency, "case {i} efficiency");
            let d = app_sleep_score(&sc, v.age, v.start, v.tz, v.chrono);
            assert_eq!(d.score, v.score, "case {i} score");
            assert_eq!(d.contributors, v.contributors, "case {i} contributors");
        }
    }

    fn unhex(s: &str) -> Vec<u8> {
        (0..s.len() / 2)
            .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
            .collect()
    }

    macro_rules! vector_tests {
        () => {
        #[test]
        fn night_matches_reference() {
            assert!(!NIGHTS.is_empty());
            for (i, v) in NIGHTS.iter().enumerate() {
                let phases = unhex(v.phases);
                let motion = unhex(v.motion);
                let night = Night {
                    age: v.age,
                    bed_start_s: v.start,
                    bed_end_s: v.end,
                    tz_min: v.tz,
                    phases: &phases,
                    phase_start_ms: v.phase_ms,
                    motion: &motion,
                    motion_start_ms: v.motion_ms,
                    chronotype: v.chrono,
                };
                let got = night_to_score(&night);
                match (got, v.want) {
                    (None, None) => {}
                    (Some(g), Some(w)) => {
                        let s = &g.sleep;
                        let args = [
                            s.time_in_bed as i64,
                            s.deep as i64,
                            s.light as i64,
                            s.rem as i64,
                            s.latency as i64,
                            s.restless as i64,
                            s.tosses as i64,
                            s.ext as i64,
                            g.timing.mid as i64,
                            g.timing.day as i64,
                            g.timing.reference as i64,
                        ];
                        assert_eq!(args, w.0, "night {i} arguments");
                        assert_eq!(g.contributors, w.1, "night {i} contributors");
                        assert_eq!(g.total, w.2, "night {i} total");
                    }
                    (g, w) => panic!("night {i}: port {g:?} vs reference {w:?}"),
                }
            }
        }
        };
    }

    mod python_port {
        use super::*;
        include!("vectors/sleep_inputs.rs");
        vector_tests!();
    }


    #[test]
    fn unpack_and_epoch_count() {
        assert_eq!(
            unpack_phases(&[0x21, 0x43, 0x03, 0x99]),
            vec![1, 2, 3, 4, 3]
        );
        assert_eq!(unpack_phases(&[0x61, 0x5F]), vec![1, 0, 0, 0]);
        assert_eq!(epoch_count(1000, 1000 + 30 * 100), 100);
        assert_eq!(epoch_count(0, 30 * 5000), ROWS);
    }

    #[test]
    fn motion_filter_is_a_trailing_four_sum() {
        let m = motion_rows(&[1, 2, 4, 8, 16, 32], 600, 600);
        assert_eq!(&m[..6], &[1, 3, 7, 15, 30, 60]);
        // samples that start one epoch before the table skip the first
        let m = motion_rows(&[100, 1, 2, 4], 570, 600);
        assert_eq!(&m[..3], &[1, 3, 7]);
        // samples that start one epoch after the table leave row 0 empty
        let m = motion_rows(&[1, 2], 630, 600);
        assert_eq!(&m[..3], &[0, 1, 3]);
    }

    #[test]
    fn stages_land_in_their_rows_off_the_grid() {
        // 60 epochs: 10 awake, 40 light, 10 deep, bedtime start 17 s past a 30 s boundary
        let mut stages = vec![4u8; 10];
        stages.extend(vec![2u8; 40]);
        stages.extend(vec![1u8; 10]);
        let start = 1_760_000_017;
        let end = start + 60 * 30;
        let off = night_from_stages(30, start, end, 0, &stages, &[], None).unwrap();
        let on = night_from_stages(30, start - 17, end - 17, 0, &stages, &[], None).unwrap();
        assert_eq!(off.scan.deep, on.scan.deep);
        assert_eq!(off.scan.light, on.scan.light);
        assert_eq!(off.scan.deep, 10);
        assert_eq!(off.scan.light, 40);
        assert!(night_from_stages(30, start, start, 0, &stages, &[], None).is_none());
    }
}
